node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get current cells
const row = db.prepare(\"SELECT cells_json FROM ob_excel_files WHERE file_path LIKE '%product_inventory%'\").get();
const cells = JSON.parse(row.cells_json);

// Add new header columns
const newHeaders = {
  'Inventory:R1C6':  'Subcategory',
  'Inventory:R1C7':  'Brand',
  'Inventory:R1C8':  'Stock Quantity',
  'Inventory:R1C9':  'Rating',
  'Inventory:R1C10': 'Review Count',
  'Inventory:R1C11': 'Description',
  'Inventory:R1C12': 'Specs',
  'Inventory:R1C13': 'Compatible With',
  'Inventory:R1C14': 'Shipping Days',
  'Inventory:R1C15': 'Gift Wrap Available',
  'Inventory:R1C16': 'Backorder Available',
  'Inventory:R1C17': 'Warranty (Months)',
  'Inventory:R1C18': 'Return Window (Days)',
  'Inventory:R1C19': 'Restocking Fee %'
};

// Add PROD-73FAB4 data for new columns (row 10)
const newData = {
  'Inventory:R10C6':  'smart home lighting',
  'Inventory:R10C7':  'Aurora Home',
  'Inventory:R10C8':  '24',
  'Inventory:R10C9':  '3.5',
  'Inventory:R10C10': '79',
  'Inventory:R10C11': 'Premium adjustable smart desk lamp with app control, USB-C charging port, and ambient presets.',
  'Inventory:R10C12': '12W LED; 2700K-6500K adjustable; Dimmable; Aluminum + ABS',
  'Inventory:R10C13': 'PROD-B98D14, PROD-FA0948, PROD-2DBA15, PROD-7C0240',
  'Inventory:R10C14': '3',
  'Inventory:R10C15': 'Yes',
  'Inventory:R10C16': 'No',
  'Inventory:R10C17': '12',
  'Inventory:R10C18': '30',
  'Inventory:R10C19': '0'
};

const updated = { ...cells, ...newHeaders, ...newData };

db.prepare(\"UPDATE ob_excel_files SET cells_json = ? WHERE file_path LIKE '%product_inventory%'\")
  .run(JSON.stringify(updated));

console.log('Updated successfully.');

// Verify
const verify = db.prepare(\"SELECT cells_json FROM ob_excel_files WHERE file_path LIKE '%product_inventory%'\").get();
const verCells = JSON.parse(verify.cells_json);
const r10keys = Object.keys(verCells).filter(k => k.startsWith('Inventory:R10')).sort();
r10keys.forEach(k => console.log(k, ':', verCells[k]));
"
